package main

import (
  "fmt"
  "net/http"
  "io"
)

func main() {

  url := "https://api.ui.com/v1/mobility/workspaces/{workspaceID}/devices/{deviceID}/clients?limit={limit}&offset={offset}"
  method := "GET"

  client := &http.Client {
  }
  req, err := http.NewRequest(method, url, nil)

  if err != nil {
    fmt.Println(err)
    return
  }
  req.Header.Add("Accept", "application/json")
  req.Header.Add("X-API-Key", "<X-API-Key>")

  res, err := client.Do(req)
  if err != nil {
    fmt.Println(err)
    return
  }
  defer res.Body.Close()

  body, err := io.ReadAll(res.Body)
  if err != nil {
    fmt.Println(err)
    return
  }
  fmt.Println(string(body))
}

